style.css:
/* Golden Hour — Google */

/* swap these colors if you want */
:root {
  --my-bg: #e9e5d5;
  --my-surface: #f5f0df;
  --my-sage: #899783;
  --my-green: #35483d;
  --my-gold: #d6ad68;
  --my-text: #343b32;
}

/* warm cinematic background */
body {
  background: linear-gradient(
    145deg,
    #d9d8c3 0%,
    var(--my-bg) 48%,
    #d8c4a2 100%
  ) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* search bar */
input[name="q"],
textarea[name="q"] {
  background: var(--my-surface) !important;
  color: var(--my-green) !important;
  border: 1px solid #b7b79e !important;
  border-radius: 28px !important;
  box-shadow: 0 5px 24px #777b5930 !important;
  padding: 14px 22px !important;
  transition: box-shadow .3s ease !important;
}

input[name="q"]:focus,
textarea[name="q"]:focus {
  box-shadow: 0 0 22px #d6ad6870 !important;
  border-color: var(--my-gold) !important;
  outline: none !important;
}

/* buttons */
button,
input[type="submit"],
[role="button"] {
  background: var(--my-sage) !important;
  color: #fff9e9 !important;
  border: 1px solid #788774 !important;
  border-radius: 22px !important;
  transition: all .25s ease !important;
}

button:hover,
input[type="submit"]:hover,
[role="button"]:hover {
  background: var(--my-green) !important;
  box-shadow: 0 3px 15px #35483d40 !important;
}

/* links */
a {
  color: #607761 !important;
  transition: color .2s ease !important;
}

a:hover {
  color: #b18a4d !important;
}

/* images */
img {
  border-radius: 5px;
}

/* subtle selection color */
::selection {
  background: var(--my-gold) !important;
  color: #28352c !important;
}
